(function(root){
function windowData(data,start,duration){const h=data?.hourly;if(!h?.time)return null;const slot=h.time.indexOf(start.slice(0,14)+'00'),first=slot<0?-1:slot+Number(start.slice(14,16))/60;if(first<0)return null;const valid=Number.isFinite(duration)&&duration>0,end=first+(valid?duration/60:0),lo=Math.max(0,Math.floor(first)-3),hi=Math.min(h.time.length-1,Math.ceil(end)+3);return{h,first,end,lo,hi,valid};}
function render(data,start,duration){const wrap=document.getElementById('weatherchart');if(!wrap)return;wrap.replaceChildren();const w=windowData(data,start,duration);if(!w){wrap.textContent='Select a site and forecast time to see the flight-window outlook.';return}const {h,first,end,lo,hi,valid}=w,ns='http://www.w3.org/2000/svg';const el=(tag,attrs,text)=>{const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs||{}))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n};const intro=document.createElement('p');intro.className='hint';intro.textContent='Model forecast · Europe/London · '+h.time[lo].replace('T',' ')+' to '+h.time[hi].replace('T',' ')+'. '+(valid?'Blue shading marks the planned '+duration+'-minute flight; dashed marker is take-off.':'Dashed marker is the selected briefing time. Set flight duration in Battery management to highlight the full flight window.')+' Hourly samples are joined for readability, not extra forecast detail.';wrap.append(intro);const grid=document.createElement('div');grid.className='weatherplots';wrap.append(grid);
const panels=[{name:'Wind · m/s',keys:[['wind_speed_10m','10 m wind','#137b69',''],['wind_gusts_10m','10 m gust','#b54732','5 3'],['wind_speed_80m','80 m wind','#7553ad','2 3']]},{name:'Precipitation chance · %',keys:[['precipitation_probability','Chance','#2678b8','']],max:100},{name:'Visibility · km',keys:[['visibility','Visibility','#137b69','']],scale:.001},{name:'Temperature · °C',keys:[['temperature_2m','Temperature','#b16c23','']]}];
for(const p of panels){const card=document.createElement('div');card.className='weatherplot';const heading=document.createElement('h3');heading.textContent=p.name;card.append(heading);const svg=el('svg',{viewBox:'0 0 520 215',role:'img','aria-label':p.name+' around the selected flight; exact hourly values are available in the expandable table.'});svg.append(el('title',{},p.name));const values=p.keys.flatMap(([key])=>h[key]?.slice(lo,hi+1).filter(v=>typeof v==='number'&&Number.isFinite(v)).map(v=>v*(p.scale||1))||[]);if(!values.length){const text=document.createElement('p');text.textContent='No forecast values available.';card.append(text);grid.append(card);continue}let min=p.name.startsWith('Temperature')?Math.floor(Math.min(...values)-1):0,max=p.max||(Math.max(min+1,...values)+Math.max(1,Math.max(...values)-min)*.15);const x=i=>46+(i-lo)/(Math.max(hi-lo,1))*454,y=v=>165-(v-min)/(max-min)*140;svg.append(el('rect',{x:x(first),y:22,width:Math.max(1,x(Math.min(end,hi))-x(first)),height:143,fill:'#dbeafe'}));for(let tick=0;tick<=4;tick++){const v=min+(max-min)*tick/4,yy=y(v);svg.append(el('line',{x1:46,x2:500,y1:yy,y2:yy,stroke:'#dbe4e7'}),el('text',{x:38,y:yy+4,'text-anchor':'end',fill:'#52616b','font-size':11},v.toFixed(p.max?0:1)))}svg.append(el('line',{x1:x(first),x2:x(first),y1:22,y2:165,stroke:'#245ea5','stroke-dasharray':'4 3'}));
for(const[key,label,color,dash]of p.keys){let segment=[];const flush=()=>{if(segment.length)svg.append(el('polyline',{points:segment.join(' '),fill:'none',stroke:color,'stroke-width':2.3,'stroke-dasharray':dash}));segment=[]};for(let i=lo;i<=hi;i++){const raw=h[key]?.[i];if(typeof raw!=='number'||!Number.isFinite(raw)){flush();continue}const v=raw*(p.scale||1);segment.push(x(i)+','+y(v));const dot=el('circle',{cx:x(i),cy:y(v),r:2.6,fill:color});dot.append(el('title',{},h.time[i].replace('T',' ')+' · '+label+': '+v.toFixed(1)));svg.append(dot)}flush()}
for(let i=lo;i<=hi;i++){if(i!==lo&&i!==hi&&(i-lo)%2)continue;svg.append(el('text',{x:x(i),y:185,'text-anchor':'middle',fill:'#52616b','font-size':11},h.time[i].slice(11)))}let lx=48;for(const[,label,color]of p.keys){svg.append(el('text',{x:lx,y:207,fill:color,'font-size':11},label));lx+=146}card.append(svg);grid.append(card)}
const rain=h.precipitation?.slice(lo,hi+1).filter(v=>typeof v==='number'&&Number.isFinite(v))||[];if(rain.length){const note=document.createElement('p');note.className='hint';note.textContent='Forecast precipitation across this displayed window: '+Math.min(...rain).toFixed(1)+'–'+Math.max(...rain).toFixed(1)+' mm/hour. Expand hourly data for exact values. Missing values appear as gaps; this display is not an airworthiness or weather clearance.';wrap.append(note)}}
root.renderFlightWeather=render;if(typeof module!=='undefined')module.exports={windowData};})(typeof window!=='undefined'?window:globalThis);
